// DnaB conceptual mechanism, not an atomistic trajectory or ATP/bp calibration.
const microDialog=document.createElement('dialog');microDialog.id='microDialog';microDialog.setAttribute('aria-labelledby','microTitle');
microDialog.innerHTML=`<div class="micro-header"><div><div class="eyebrow">进一步探索 · 分子尺度</div><h2 id="microTitle">解旋酶怎样打开 DNA？</h2><p>以细菌 DnaB 为例 · 六亚基环状解旋酶</p></div><button id="closeMicro" aria-label="关闭分子视图">关闭</button></div><div class="micro-view-switch" role="group" aria-label="选择模型类型"><button id="showTeaching" aria-pressed="true">教学动画</button><button id="showStructure" aria-pressed="false">真实结构 · PDB 4ESV</button></div><section id="realStructure" hidden><p class="structure-provenance"><strong>实验结构快照 · X 射线衍射 · 3.20 Å</strong><br>来源：Geobacillus stearothermophilus 的 DnaB，生物学组装体 1。配体为 GDP–AlF₄；用于观察环状结构、DNA 和结合位点，不代表 ATP 水解的四个连续状态。</p><iframe id="structureFrame" title="DnaB 实验结构三维查看器" loading="lazy"></iframe><p class="structure-provenance">数据：<a href="https://www.rcsb.org/structure/4ESV" target="_blank" rel="noopener">RCSB PDB · 4ESV</a> · <a href="https://doi.org/10.1016/j.cell.2012.09.014" target="_blank" rel="noopener">Itsathitphaisarn 等，Cell (2012)</a>。显示用飘带与球棍表达实验坐标，未显示所有溶剂分子。查看器：<a href="https://doi.org/10.1093/nar/gkab314" target="_blank" rel="noopener">Mol* / Sehnal 等 (2021)</a>。</p></section><div class="micro-grid" id="teachingStructure"><section class="micro-model"><svg id="microSvg" viewBox="0 0 640 400" role="img" aria-labelledby="microSvgTitle microSvgDesc"><title id="microSvgTitle">DnaB 解旋与 ATP 循环示意</title><desc id="microSvgDesc"></desc><defs><marker id="microArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#78dfc4"/></marker></defs><g id="microDrawing"></g></svg><div class="micro-legend"><span>青色：被环包围的链</span><span>橙色：排除链</span><span>虚线：碱基间氢键示意</span></div><div class="micro-controls"><button id="microPrev">上一步</button><button id="microPlay">播放过程</button><button id="microNext">下一步</button></div><div id="microSteps" class="micro-steps" role="group" aria-label="分子机制步骤"></div></section><section class="micro-explain" aria-live="polite"><span id="microNumber" class="eyebrow"></span><h3 id="microHeading"></h3><p id="microText"></p><div class="chemical"><span>ATP 水解 · 简化总反应</span><div class="equation"><span id="chemATP">ATP</span> + <span id="chemWater">H₂O</span> → <span id="chemADP">ADP</span> + <span id="chemPi">Pᵢ</span></div><p id="chemCaption"></p></div><p class="micro-key">解开的是双链间的配对；DNA 单链的糖–磷酸骨架保持完整。</p></section></div><details class="micro-details"><summary>进一步理解：能量、化学键与模型边界</summary><div><p><strong>能量从哪里来？</strong>ATP 水解的整体自由能变化可与蛋白质构象变化和定向运动耦联。不能把“断开 ATP 的一个键”本身说成释放能量；断键需要能量，整个反应的能量收支还包括新键形成及产物与水的相互作用。</p><p><strong>反应式省略了什么？</strong>Pᵢ 表示无机磷酸。此式省略电荷、质子化状态和 Mg²⁺ 配位；它是生化简写，不是指定 pH 下的完整离子方程式。ATP 没有变成 DNA 的组成部分。</p><p><strong>DNA 为什么能分开？</strong>解旋涉及碱基间氢键及碱基堆积相互作用的改变，不是把共价骨架剪断。模型的虚线只代表配对关系，没有按 A–T 两个、G–C 三个氢键逐一绘制。</p><p><strong>模型边界。</strong>本视图把结合、水解、构象变化和产物释放拆成四个学习阶段；真实六个亚基会协同工作，不能据此推断严格的同步时序或 ATP/碱基对比例。亚基形状、运动幅度和空间尺寸为示意，未显示原子结构、加载蛋白或完整复制复合体。真核复制解旋酶的组成与运动方向不同。</p><p>机制依据：<a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC5704481/" target="_blank" rel="noopener">DnaB 与排除链的相互作用</a>；<a href="https://pubmed.ncbi.nlm.nih.gov/11061975/" target="_blank" rel="noopener">DnaB ATP 结合、水解与构象转变研究</a>。</p></div></details>`;
document.body.append(microDialog);
const microStages=[
 ['ATP 结合','ATP binding','ATP 与酶的核苷酸结合位点结合。DnaB 环包围一条单链；另一条链走环的外侧。','高亮 ATP：此时强调结合，尚未在图中显示水解产物。'],
 ['水参与水解','ATP hydrolysis','结合的 ATP 经水解形成 ADP 与无机磷酸（Pᵢ）。化学反应与蛋白质的状态变化相联系。','高亮 H₂O、ADP 与 Pᵢ：水参与反应，末端磷酸成为无机磷酸。'],
 ['构象改变，推进解旋','Conformational coupling','亚基与 DNA 的接触关系改变，运动与核苷酸循环耦联。DnaB 沿包围链的 5′→3′ 方向推进，使另一条链被排开。','反应与机械运动耦联；此图的移动距离不对应一个 ATP 或一个碱基对。'],
 ['产物释放，继续循环','Product release','ADP 与 Pᵢ 释放，位点可参与后续循环。多亚基协同使解旋继续，已分开的两条 DNA 骨架仍完整。','产物离开酶：继续解旋需要后续核苷酸循环。']
];
let microStep=0,microTimer=null,microOpener=null,microPlayer=null;
function microStop(){microPlayer?.pause();microTimer=null;$('microPlay').textContent='播放过程'}
function microRender(){const s=microStages[microStep];$('microNumber').textContent=`0${microStep+1} / 04 · ${s[1]}`;$('microHeading').textContent=s[0];$('microText').textContent=s[2];$('chemCaption').textContent=s[3];$('microSvgDesc').textContent=s[2];$('microPrev').disabled=microStep===0;$('microNext').textContent=microStep===3?'再看一遍':'下一步';[...$('microSteps').children].forEach((b,i)=>b.setAttribute('aria-pressed',i===microStep));for(const id of ['chemATP','chemWater','chemADP','chemPi'])$(id).classList.toggle('chem-active',microStep===0?id==='chemATP':microStep===1?id!=='chemATP':id==='chemADP'||id==='chemPi');
 const advance=microStep>=2?36:0,fork=380+advance,cx=300+advance;
 let svg=`<text x="24" y="30" fill="#9fb7c9" font-size="14">DnaB · 局部剖视示意 · 非原子模型</text><path d="M50 270 Q200 250 ${fork} 215 L590 215" fill="none" stroke="#78dfc4" stroke-width="7"/><path d="M50 105 Q220 95 ${fork} 185 L590 185" fill="none" stroke="#ffba73" stroke-width="7"/>`;
 for(let x=440;x<=580;x+=20){svg+=`<path d="M${x} 186V197 M${x} 203V214" stroke="#c9d5e4" stroke-width="4"/><path d="M${x} 197V203" stroke="#c9d5e4" stroke-width="2" stroke-dasharray="2 2"/>`}
 if(microStep<2)for(let x=393;x<430;x+=18)svg+=`<path d="M${x} 186V214" stroke="#c9d5e4" stroke-width="2" stroke-dasharray="3 3"/>`;
 for(let i=0;i<6;i++){const a=i*Math.PI/3,x=cx+Math.cos(a)*39,y=230+Math.sin(a)*52,active=i===0||i===5;svg+=`<ellipse cx="${x}" cy="${y}" rx="24" ry="26" fill="${active&&microStep===2?'#65b7eb':'#294a6b'}" fill-opacity=".88" stroke="${active?'#91d1ff':'#6086aa'}" stroke-width="2"/><text x="${x}" y="${y+5}" text-anchor="middle" font-size="13" fill="#e8f3ff">${i+1}</text>`}
 svg+=`<text x="35" y="295" fill="#78dfc4" font-size="16">5′</text><text x="603" y="222" fill="#78dfc4" font-size="16">3′</text><text x="35" y="91" fill="#ffba73" font-size="16">3′</text><text x="603" y="187" fill="#ffba73" font-size="16">5′</text><text x="65" y="137" fill="#ffba73" font-size="14">排除链 · 环外</text><text x="65" y="321" fill="#78dfc4" font-size="14">包围链 · 穿过中央通道</text><path d="M250 334H405" stroke="#78dfc4" stroke-width="2" marker-end="url(#microArrow)"/><text x="250" y="363" fill="#bcd4df" font-size="14">DnaB 沿包围链 5′→3′ 运动</text>`;
 let tx=cx+42,ty=microStep===3?73:136;svg+=`<path d="M${cx+34} 199L${tx+20} ${ty+26}" stroke="#eb88c5" stroke-dasharray="4 4"/><rect x="${tx-16}" y="${ty}" width="${microStep===0?65:116}" height="30" rx="8" fill="#452e4c" stroke="#eb88c5"/><text x="${tx-5}" y="${ty+20}" fill="#ffc1e8" font-size="15">${microStep===0?'ATP':'ADP + Pᵢ'}</text>`;
 if(microStep===1)svg+=`<text x="${tx-10}" y="${ty-13}" fill="#b4ddfb" font-size="15">+ H₂O</text>`;
 if(microStep>=2)svg+=`<text x="432" y="275" fill="#cedce8" font-size="14">配对分开</text><path d="M437 256L420 203" stroke="#93aabd" stroke-width="1"/>`;
 $('microDrawing').innerHTML=svg;
}
function openMicro(){playing=false;$('play').textContent='播放';microOpener=document.activeElement;microStop();microPlayer.seek(0);showMolecularView(false);if(!microDialog.open)microDialog.showModal();$('closeMicro').focus()}
window.openMicro=openMicro;

microPlayer=new LessonPlayer({count:microStages.length,onStep:i=>{microStep=i;microRender()},onPlay:running=>{$('microPlay').textContent=running?'暂停':'播放过程'}});
microStages.forEach((s,i)=>{let b=document.createElement('button');b.textContent=(i+1)+' '+s[0];b.onclick=()=>microPlayer.seek(i);$('microSteps').append(b)});
$('microPrev').onclick=()=>microPlayer.previous();$('microNext').onclick=()=>microPlayer.next();$('microPlay').onclick=()=>microPlayer.play();
function showMolecularView(real){microStop();$('teachingStructure').hidden=real;$('realStructure').hidden=!real;$('showTeaching').setAttribute('aria-pressed',!real);$('showStructure').setAttribute('aria-pressed',real);if(real){const frame=$('structureFrame');if(!frame.getAttribute('src'))frame.src='structure-viewer.html?lang='+BioI18n.language;else frame.contentWindow?.postMessage({type:'biolens-structure-resize'},location.origin)}}
$('showTeaching').onclick=()=>showMolecularView(false);$('showStructure').onclick=()=>showMolecularView(true);
$('closeMicro').onclick=()=>microDialog.close();microDialog.addEventListener('close',()=>{microStop();$('structureFrame').contentWindow?.postMessage({type:'biolens-structure-pause'},location.origin);microOpener?.focus?.()});$('openMicro').onclick=openMicro;
